    Text = "মানচিত্রে চলাফেরা ও তদন্ত ইভেন্ট মানসিক চাপ তৈরি করবে, চাপ জমা হলে গোপনরক্ষক উপসর্গে আক্রান্ত হবে।\nপ্রতি এক ঘর চলাফেরায় চাপ ১০ পয়েন্ট বাড়ে। প্রতি ১০০ পয়েন্ট চাপে ১টি উপসর্গ পাওয়া যায়।\nচাপ ৫০০-এ পৌঁছানোর পর, প্রতি এক ঘর চলাফেরায় ১০% জীবনী শক্তি কাটা হবে।"
  },
  TipsType_40002_Title = {Text = "চাপ"},
  TipsType_40003_Desc = {
    Text = "উচ্চতর অ্যাসাইনমেন্ট স্তর মানে বেশি কঠিনতা, কিন্তু আরও ভালো পুরস্কার।"
  },
  TipsType_40003_Title = {
    Text = "কার্যভার স্তর"
  },
  TipsType_40004_Desc = {
    Text = "প্রতি টার্নে প্রথম যে কমান্ড কার্ডটি খেলা হয়, সেটি আল্ট্রা স্পেসে একটি অস্থায়ী অনুলিপি সৃষ্টি করে।\nপূর্ণ হলে, 1টি অতিরিক্ত আল্ট্রা রাউন্ড পাও এবং আগের টার্নের শিল্ড বজায় রাখো।\nরিয়েল্ম দক্ষতা প্রভাব: টার্নের শুরুতে হাতে 1টি 「Insight」 যোগ হওয়ার একটি সম্ভাবনা থাকে।"
  },
  TipsType_40004_Title = {
    Text = "আল্ট্রা স্পেস"
  },
  TipsType_40005_Desc = {
    Text = "রক্ষকেরা তদন্ত, অন্তর্বর্তী মহড়া এবং চ্যালেঞ্জের মাধ্যমে রক্ষক EXP অর্জন করে। উচ্চতর রক্ষক স্তর আরও বেশি গেমপ্লে বিকল্প উন্মুক্ত করে।"
  },
  TipsType_40005_Title = {
    Text = "রক্ষক অভিজ্ঞতা"
  },
  TipsType_40006_Desc = {
    Text = "কমান্ড কার্ডগুলো অ্যারিথমেটিকা ব্যয় করে। অব্যবহৃত পয়েন্ট পরের টার্নে যায় না। প্রতিটি টার্নের শুরুতে অ্যারিথমেটিকা সম্পূর্ণ পুনরুদ্ধার হয়।"
  },
  TipsType_40006_Title = {
    Text = "অ্যারিথমেটিকা"
  },
  TipsType_40007_Desc = {
    Text = "রৌপ্য চাবি বিশেষ শক্তি শনাক্ত করে। এখানে হয়তো কোনো মূল্যবান বস্তু লুকিয়ে আছে..."
  },
  TipsType_40007_Title = {
    Text = "লুকায়িত সম্পদ"
  },
  TipsType_40008_Desc = {
    Text = "মারাত্মক সঙ্কটে সক্রিয় হয় (1টি ব্যবহার খরচ হয়)।\nদলের HP এবং জাগ্রতদের অ্যালিমাস সর্বোচ্চ মানে পুনরুদ্ধার করে।\nদৈনিক রিফ্রেশ: সকাল 9টায় 1 বার।"
  },
  TipsType_40008_Title = {
    Text = "জরুরি নসিস"
  },
  TipsType_40009_Desc = {
    Text = "কমান্ড কার্ড ব্যবহার করতে অ্যারিথমেটিকা খরচ হয়। অব্যবহৃত পয়েন্ট মেয়াদোত্তীর্ণ হয়।\nটার্নের শুরুতে: সর্বোচ্চ সীমা +1, এবং পয়েন্ট সেই সীমা পর্যন্ত পুনরুদ্ধার হয়। বর্তমান টার্ন: {s1}।"
  },
  TipsType_40009_Title = {
    Text = "অ্যারিথমেটিকা"
  },
