    Text = "আঞ্চলিক ডি-ইফেক্ট নিষিদ্ধ অঞ্চল রিসেট হয়েছে, চলমান চ্যালেঞ্জ তাৎক্ষণিকভাবে শেষ হয়ে যাবে।"
